    long long powerOfTenPlusOne = 1, digitCount = 1;
    while (powerOfTenPlusOne <= n) {
        powerOfTenPlusOne = powerOfTenPlusOne * 10 + 1;
        digitCount++;
    }
    digitCount--;
    powerOfTenPlusOne = (powerOfTenPlusOne - 1) / 10;
    if (powerOfTenPlusOne == n) return digitCount;
