import java.util.Scanner;

public class Main {
    public static long computeSteps(long n) {
        if (n == 0) return 0;
        long powerOfTenPlusOne = 1, digitCount = 1;
        while (powerOfTenPlusOne <= n) {
            powerOfTenPlusOne = powerOfTenPlusOne * 10 + 1;
            digitCount++;
        }
        digitCount--;
        powerOfTenPlusOne = (powerOfTenPlusOne - 1) / 10;
        if (powerOfTenPlusOne == n) return digitCount;
        long minMoves = Long.MAX_VALUE;
        if ((powerOfTenPlusOne * 10 + 1 - n) < n) {
            minMoves = computeSteps(powerOfTenPlusOne * 10 + 1 - n) + digitCount + 1;
        }
        long multiple = 1;
        long candidateVal;
        while (powerOfTenPlusOne * multiple <= n) {
            candidateVal = powerOfTenPlusOne * multiple;
            multiple++;
        }
        multiple--;
        long alternativeMoves = computeSteps(n - candidateVal) + digitCount * (multiple - 1);
        return Math.min(minMoves, alternativeMoves);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long input = scanner.nextLong();
        System.out.println(computeSteps(input));
        scanner.close();
    }
}
